const KEYS = {
  weather: "ВСТАВ_СВІЙ_OPENWEATHER_API_KEY",
  news: "ВСТАВ_СВІЙ_NEWSAPI_KEY",
  pixabay: "ВСТАВ_СВІЙ_PIXABAY_API_KEY",
};

async function request(url) {
  const response = await fetch(url);

  if (!response.ok) {
    throw new Error(`Помилка запиту: ${response.status}`);
  }

  return response.json();
}

export async function getWeather(city) {
  return request(
    `https://api.openweathermap.org/data/2.5/weather?q=${encodeURIComponent(city)}&appid=${KEYS.weather}&units=metric&lang=uk`
  );
}

export async function getForecast(city) {
  return request(
    `https://api.openweathermap.org/data/2.5/forecast?q=${encodeURIComponent(city)}&appid=${KEYS.weather}&units=metric&lang=uk`
  );
}

export async function getNews() {
  return request(
    `https://newsapi.org/v2/everything?q=weather%20OR%20nature&language=en&sortBy=publishedAt&pageSize=6&apiKey=${KEYS.news}`
  );
}

export async function getNaturePhotos() {
  return request(
    `https://pixabay.com/api/?key=${KEYS.pixabay}&q=nature%20landscape&image_type=photo&orientation=horizontal&per_page=10&safesearch=true`
  );
}
